": \"sha512-BNGbWLfd0eUPabhkXUVm0j8uuvREyTh5ovRa/dyow/BqAbZJyC+5fU+IzQOzmAKzYqYRAISoRhdQr3eIZ/PXqg==\",\n      \"license\": \"MIT\",\n      \"engines\": {\n        \"node\": \">= 0.8\"\n      }\n    },\n    \"node_modules/wrappy\": {\n      \"version\": \"1.0.2\",\n      \"resolved\": \"https://registry.npmjs.org/wrappy/-/wrappy-1.0.2.tgz\",\n      \"integrity\": \"sha512-l4Sp/DRseor9wL6EvV2+TuQn63dMkPjZ/sp9XkghTEbV9KlPS1xUsZ3u7/IQO4wxtcFB4bgpQPRcR3QCvezPcQ==\",\n      \"dev\": true,\n      \"license\": \"ISC\"\n    },\n    \"node_modules/xtend\": {\n      \"version\": \"4.0.2\",\n      \"resolved\": \"https://registry.npmjs.org/xtend/-/xtend-4.0.2.tgz\",\n      \"integrity\": \"sha512-LKYU1iAXJXUgAXn9URjiu+MWhyUXHsvfp7mcuYm9dSUKK0/CjtrUwFAxD82/mCWbtLsGjFIad0wIsod4zrTAEQ==\",\n      \"dev\": true,\n      \"license\": \"MIT\",\n      \"engines\": {\n        \"node\": \">=0.4\"\n      }\n    },\n    \"node_modules/yn\": {\n      \"version\": \"3.1.1\",\n      \"resolved\": \"https://registry.npmjs.org/yn/-/yn-3.1.1.tgz\",\n      \"integrity\": \"sha512-Ux4ygGWsu2c7isFWe8Yu1YluJmqVhxqK2cLXNQA5AcC3QfbGNpM7fu0Y8b/z16pXLnFxZYvWhd3fhBY9DLmC6Q==\",\n      \"dev\": true,\n      \"license\": \"MIT\",\n      \"engines\": {\n        \"node\": \">=6\"\n      }\n    }\n  }\n}\n";
files["backend/package.json"] = "{\n  \"name\": \"dental-marketplace-backend\",\n  \"version\": \"1.0.0\",\n  \"description\": \"API do marketplace de aluguel de consultorios odontologicos\",\n  \"main\": \"dist/server.js\",\n  \"scripts\": {\n    \"dev\": \"ts-node-dev --respawn --transpile-only src/server.ts\",\n    \"build\": \"tsc -p tsconfig.json\",\n    \"start\": \"node dist/server.js\"\n  },\n  \"dependencies\": {\n    \"cors\": \"^2.8.5\",\n    \"express\": \"^4.19.2\"\n  },\n  \"devDependencies\": {\n    \"@types/cors\": \"^2.8.17\",\n    \"@types/express\": \"^4.17.21\",\n    \"@types/node\": \"^20.14.2\",\n    \"ts-node-dev\": \"^2.0.0\",\n    \"typescript\": \"^5.5.2\"\n  }\n}\n";
files["backend/src/modules/admin/admin.controller.ts"] = "import { Request, Response } from \"express\";\nimport { adminService } from \"./admin.service\";\nimport { userService, AuthError } from \"../users/user.service\";\nimport { officeService, OfficeValidationError } from \"../offices/office.service\";\n\nfunction handleError(res: Response, error: unknown) {\n  if (error instanceof AuthError || error instanceof OfficeValidationError) {\n    return res.status(400).json({ message: error.message });\n  }\n  console.error(error);\n  return res.status(500).json({ message: \"Erro interno no servidor.\" });\n}\n\nexport const adminController = {\n  async getMetrics(_req: Request, res: Response) {\n    try {\n      const metrics = await adminService.getMetrics();\n      return res.status(200).json(metrics);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async getFinanceSummary(_req: Request, res: Response) {\n    try {\n      const finance = await adminService.getFinanceSummary();\n      return res.status(200).json(finance);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  // ---------- Usuários ----------\n\n  async listUsers(_req: Request, res: Response) {\n    try {\n      const users = await userService.listAll();\n      return res.status(200).json(users);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async toggleBanUser(req: Request, res: Response) {\n    try {\n      // Admin não pode banir a si mesmo.\n      if (req.params.id === req.authUser?.id) {\n        return res.status(400).json({ message: \"Você não pode banir a própria conta.\" });\n      }\n      const user = await userService.toggleBan(req.params.id);\n      return res.status(200).json(user);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async togglePromoteUser(req: Request, res: Response) {\n    try {\n      const user = await userService.togglePromote(req.params.id);\n      return res.status(200).json(user);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  // ---------- Moderação de Clínicas ----------\n\n  async listPendingOffices(_req: Request, res: Response) {\n    try {\n      const offices = await officeService.listPending();\n      return res.status(200).json(offices);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async approveOffice(req: Request, res: Response) {\n    try {\n      const office = await officeService.approve(req.params.id);\n      return res.status(200).json(office);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async rejectOffice(req: Request, res: Response) {\n    try {\n      const office = await officeService.reject(req.params.id);\n      return res.status(200).json(office);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n};\n";
files["backend/src/modules/admin/admin.routes.ts"] = "import { Router } from \"express\";\nimport { adminController } from \"./admin.controller\";\nimport { requireAdmin } from \"../../shared/middlewares/auth.middleware\";\n\nconst adminRoutes = Router();\n\n// Todas as rotas abaixo exigem um usuário autenticado com role \"admin\".\nadminRoutes.use(\"/admin\", requireAdmin);\n\nadminRoutes.get(\"/admin/metrics\", adminController.getMetrics);\nadminRoutes.get(\"/admin/finance\", adminController.getFinanceSummary);\n\nadminRoutes.get(\"/admin/users\", adminController.listUsers);\nadminRoutes.patch(\"/admin/users/:id/ban\", adminController.toggleBanUser);\nadminRoutes.patch(\"/admin/users/:id/promote\", adminController.togglePromoteUser);\n\nadminRoutes.get(\"/admin/offices/pending\", adminController.listPendingOffices);\nadminRoutes.patch(\"/admin/offices/:id/approve\", adminController.approveOffice);\nadminRoutes.patch(\"/admin/offices/:id/reject\", adminController.rejectOffice);\n\nexport { adminRoutes };\n";
files["backend/src/modules/admin/admin.service.ts"] = "import { officeRepository } from \"../offices/office.repository\";\nimport { userRepository } from \"../users/user.repository\";\n\n// Módulo \"admin\" é um agregador (BFF) que lê dados de outros módulos\n// (offices, users) para montar visões gerenciais. Ele não duplica regras\n// de negócio: ações de escrita (banir, aprovar, etc.) continuam vivendo\n// nos services originais (userService, officeService); este módulo só\n// orquestra e resume os dados para a tela /admin.\n\n// Taxa de comissão simulada da plataforma sobre o \"faturamento\" estimado.\nconst PLATFORM_FEE_PERCENT = 12;\n\nexport const adminService = {\n  async getMetrics() {\n    const [offices, users] = await Promise.all([officeRepository.findAll(), userRepository.findAll()]);\n\n    const activeOffices = offices.filter((o) => o.status === \"ATIVO\" && o.moderationStatus === \"APROVADO\");\n    const pendingOffices = offices.filter((o) => o.moderationStatus === \"PENDENTE\");\n    const rejectedOffices = offices.filter((o) => o.moderationStatus === \"RECUSADO\");\n    const bannedUsers = users.filter((u) => u.status === \"BANIDO\");\n    const admins = users.filter((u) => u.role === \"admin\");\n\n    const totalReviews = offices.reduce((sum, o) => sum + (o.reviews?.length ?? 0), 0);\n    const avgRating =\n      offices.length > 0\n        ? offices.reduce((sum, o) => sum + (o.rating ?? 0), 0) / offices.length\n        : 0;\n\n    return {\n      totalUsers: users.length,\n      totalAdmins: admins.length,\n      bannedUsers: bannedUsers.length,\n      totalOffices: offices.length,\n      activeOffices: activeOffices.length,\n      pendingOffices: pendingOffices.length,\n      rejectedOffices: rejectedOffices.length,\n      totalReviews,\n      averageRating: Number(avgRating.toFixed(2)),\n    };\n  },\n\n  // Painel de finanças 100% simulado — não há módulo de pagamentos ainda.\n  // Estima receita somando o menor preço de turno de cada consultório ATIVO\n  // e aprovado, multiplicado por um número fixo de reservas/mês fictício,\n  // só para dar uma noção visual de escala no dashboard.\n  async getFinanceSummary() {\n    const offices = await officeRepository.findAll({ status: \"ATIVO\", moderationStatus: \"APROVADO\" });\n\n    const MOCK_BOOKINGS_PER_OFFICE_PER_MONTH = 8;\n\n    const estimatedMonthlyGrossRevenue = offices.reduce((sum, o) => {\n      const cheapestShift = Math.min(...o.shiftPrices.map((sp) => sp.price));\n      return sum + cheapestShift * MOCK_BOOKINGS_PER_OFFICE_PER_MONTH;\n    }, 0);\n\n    const platformFeeRevenue = estimatedMonthlyGrossRevenue * (PLATFORM_FEE_PERCENT / 100);\n    const hostPayoutTotal = estimatedMonthlyGrossRevenue - platformFeeRevenue;\n\n    // Série mensal fictícia (últimos 6 meses) só para dar uma ideia de tendência.\n    const monthlyTrend = [0.62, 0.7, 0.68, 0.81, 0.9, 1].map((factor) => ({\n      grossRevenue: Number((estimatedMonthlyGrossRevenue * factor).toFixed(2)),\n    }));\n\n    return {\n      platformFeePercent: PLATFORM_FEE_PERCENT,\n      estimatedMonthlyGrossRevenue: Number(estimatedMonthlyGrossRevenue.toFixed(2)),\n      platformFeeRevenue: Number(platformFeeRevenue.toFixed(2)),\n      hostPayoutTotal: Number(hostPayoutTotal.toFixed(2)),\n      activeListingsConsidered: offices.length,\n      monthlyTrend,\n      isSimulated: true,\n    };\n  },\n};\n";
files["backend/src/modules/bookings/booking.controller.ts"] = "import { Request, Response } from \"express\";\nimport { BookingValidationError, bookingService } from \"./booking.service\";\n\nfunction handleError(res: Response, error: unknown) {\n  if (error instanceof BookingValidationError) {\n    return res.status(400).json({ message: error.message });\n  }\n  console.error(error);\n  return res.status(500).json({ message: \"Erro interno no servidor.\" });\n}\n\nexport const bookingController = {\n  async create(req: Request, res: Response) {\n    try {\n      // dentistId nunca vem do corpo da requisição — sempre do usuário autenticado.\n      const dentistId = req.authUser!.id;\n      const booking = await bookingService.create(dentistId, req.body);\n      return res.status(201).json(booking);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async listReceived(req: Request, res: Response) {\n    try {\n      const ownerId = req.authUser!.id;\n      const status = req.query.status as string | undefined;\n      const bookings = await bookingService.listReceived(ownerId, status);\n      return res.status(200).json(bookings);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async listSent(req: Request, res: Response) {\n    try {\n      const dentistId = req.authUser!.id;\n      const status = req.query.status as string | undefined;\n      const bookings = await bookingService.listSent(dentistId, status);\n      return res.status(200).json(bookings);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async getById(req: Request, res: Response) {\n    try {\n      const booking = await bookingService.getById(req.params.id);\n      const userId = req.authUser!.id;\n      if (booking.ownerId !== userId && booking.dentistId !== userId) {\n        return res.status(403).json({ message: \"Você não tem acesso a esta proposta.\" });\n      }\n      return res.status(200).json(booking);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async accept(req: Request, res: Response) {\n    try {\n      const booking = await bookingService.accept(req.params.id, req.authUser!.id);\n      return res.status(200).json(booking);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async reject(req: Request, res: Response) {\n    try {\n      const booking = await bookingService.reject(req.params.id, req.authUser!.id);\n      return res.status(200).json(booking);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async addMessage(req: Request, res: Response) {\n    try {\n      const senderId = req.authUser!.id;\n      const booking = await bookingService.addMessage(req.params.id, senderId, req.body.text);\n      return res.status(200).json(booking);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n};\n";
files["backend/src/modules/bookings/booking.model.ts"] = "import { Shift, Weekday } from \"../offices/office.model\";\n\n// Status do ciclo de vida de uma proposta de reserva.\nexport type BookingStatus = \"PENDENTE_APROVACAO\" | \"ACEITO\" | \"RECUSADO\" | \"NEGOCIACAO\";\n\n// Mensagem trocada entre proprietário e dentista sobre uma proposta específica.\n// É um \"chat\" simples embutido na proposta — não é o módulo de chat geral\n// da plataforma (que ainda não existe), mas resolve o caso de uso de\n// \"Negociar\" pedido nesta rodada.\nexport interface ChatMessage {\n  id: string;\n  senderId: string;\n  senderName: string;\n  text: string;\n  createdAt: string;\n  isAutoGenerated?: boolean;\n}\n\nexport interface BookingProposal {\n  id: string;\n  officeId: string;\n  officeTitle: string; // denormalizado para não precisar de outro fetch na listagem\n  officeImageUrl?: string;\n  ownerId: string; // proprietário do consultório — quem recebe a proposta\n  dentistId: string; // quem está propondo a reserva\n  dentistName: string;\n  dentistAvatarUrl: string;\n  date: string; // \"YYYY-MM-DD\"\n  weekday: Weekday;\n  shift: Shift;\n  serviceId?: string;\n  serviceName: string; // ex: \"Procedimento de Canal\" ou \"Turno padrão\"\n  listedPrice: number; // preço tabelado (do serviço ou do turno) no momento da proposta\n  offeredPrice: number; // valor efetivamente ofertado pelo dentista\n  status: BookingStatus;\n  messages: ChatMessage[];\n  createdAt: string;\n  updatedAt: string;\n}\n\nexport interface CreateBookingDTO {\n  officeId: string;\n  date: string; // \"YYYY-MM-DD\"\n  shift: Shift;\n  serviceId?: string;\n  offeredPrice: number;\n}\n";
files["backend/src/modules/bookings/booking.repository.ts"] = "import { BookingProposal } from \"./booking.model\";\n\nexport interface IBookingRepository {\n  create(booking: BookingProposal): Promise<BookingProposal>;\n  findById(id: string): Promise<BookingProposal | null>;\n  findByOwner(ownerId: string, status?: string): Promise<BookingProposal[]>;\n  findByDentist(dentistId: string, status?: string): Promise<BookingProposal[]>;\n  // Procura propostas do mesmo dentista, na mesma data/turno, com status\n  // PENDENTE_APROVACAO ou ACEITO — usado para a regra de conflito de agenda.\n  findActiveConflict(\n    dentistId: string,\n    date: string,\n    shift: string,\n    excludeBookingId?: string\n  ): Promise<BookingProposal | null>;\n  update(id: string, patch: Partial<BookingProposal>): Promise<BookingProposal | null>;\n}\n\nclass BookingInMemoryRepository implements IBookingRepository {\n  private bookings: BookingProposal[] = [];\n\n  async create(booking: BookingProposal): Promise<BookingProposal> {\n    this.bookings.push(booking);\n    return booking;\n  }\n\n  async findById(id: string): Promise<BookingProposal | null> {\n    return this.bookings.find((b) => b.id === id) ?? null;\n  }\n\n  async findByOwner(ownerId: string, status?: string): Promise<BookingProposal[]> {\n    let result = this.bookings.filter((b) => b.ownerId === ownerId);\n    if (status) result = result.filter((b) => b.status === status);\n    return result.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());\n  }\n\n  async findByDentist(dentistId: string, status?: string): Promise<BookingProposal[]> {\n    let result = this.bookings.filter((b) => b.dentistId === dentistId);\n    if (status) result = result.filter((b) => b.status === status);\n    return result.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());\n  }\n\n  async findActiveConflict(\n    dentistId: string,\n    date: string,\n    shift: string,\n    excludeBookingId?: string\n  ): Promise<BookingProposal | null> {\n    return (\n      this.bookings.find(\n        (b) =>\n          b.dentistId === dentistId &&\n          b.date === date &&\n          b.shift === shift &&\n          (b.status === \"PENDENTE_APROVACAO\" || b.status === \"ACEITO\") &&\n          b.id !== excludeBookingId\n      ) ?? null\n    );\n  }\n\n  async update(id: string, patch: Partial<BookingProposal>): Promise<BookingProposal | null> {\n    const index = this.bookings.findIndex((b) => b.id === id);\n    if (index === -1) return null;\n    this.bookings[index] = {\n      ...this.bookings[index],\n      ...patch,\n      id: this.bookings[index].id,\n      updatedAt: new Date().toISOString(),\n    };\n    return this.bookings[index];\n  }\n}\n\nexport const bookingRepository: IBookingRepository = new BookingInMemoryRepository();\n";
files["backend/src/modules/bookings/booking.routes.ts"] = "import { Router } from \"express\";\nimport { bookingController } from \"./booking.controller\";\nimport { requireAuth } from \"../../shared/middlewares/auth.middleware\";\n\nconst bookingRoutes = Router();\n\nbookingRoutes.use(\"/bookings\", requireAuth);\n\nbookingRoutes.post(\"/bookings\", bookingController.create);\nbookingRoutes.get(\"/bookings/received\", bookingController.listReceived); // propostas recebidas (proprietário)\nbookingRoutes.get(\"/bookings/sent\", bookingController.listSent); // propostas enviadas (dentista)\nbookingRoutes.get(\"/bookings/:id\", bookingController.getById);\nbookingRoutes.patch(\"/bookings/:id/accept\", bookingController.accept);\nbookingRoutes.patch(\"/bookings/:id/reject\", bookingController.reject);\nbookingRoutes.post(\"/bookings/:id/messages\", bookingController.addMessage);\n\nexport { bookingRoutes };\n";
files["backend/src/modules/bookings/booking.service.ts"] = "import { randomUUID } from \"crypto\";\nimport { officeRepository } from \"../offices/office.repository\";\nimport { userRepository } from \"../users/user.repository\";\nimport { JS_WEEKDAY_TO_WEEKDAY } from \"../offices/office.model\";\nimport { BookingProposal, ChatMessage, CreateBookingDTO } from \"./booking.model\";\nimport { bookingRepository } from \"./booking.repository\";\n\nexport class BookingValidationError extends Error {\n  constructor(message: string) {\n    super(message);\n    this.name = \"BookingValidationError\";\n  }\n}\n\nfunction parseDateOrThrow(date: string): Date {\n  const parsed = new Date(`${date}T12:00:00`); // meio-dia evita bug de fuso na borda do dia\n  if (isNaN(parsed.getTime())) throw new BookingValidationError(\"Data inválida.\");\n  return parsed;\n}\n\nfunction buildAutoMessage(booking: BookingProposal): ChatMessage {\n  const text =\n    `📋 Nova proposta de reserva recebida!\\n` +\n    `Dentista: ${booking.dentistName}\\n` +\n    `Consultório: ${booking.officeTitle}\\n` +\n    `Data: ${new Date(`${booking.date}T12:00:00`).toLocaleDateString(\"pt-BR\")} (${booking.weekday}) — Turno: ${booking.shift}\\n` +\n    `Procedimento: ${booking.serviceName}\\n` +\n    `Valor tabelado: R$ ${booking.listedPrice.toFixed(2)} · Valor ofertado: R$ ${booking.offeredPrice.toFixed(2)}`;\n\n  return {\n    id: randomUUID(),\n    senderId: booking.dentistId,\n    senderName: booking.dentistName,\n    text,\n    createdAt: new Date().toISOString(),\n    isAutoGenerated: true,\n  };\n}\n\nexport const bookingService = {\n  async create(dentistId: string, data: CreateBookingDTO): Promise<BookingProposal> {\n    if (!data.officeId) throw new BookingValidationError(\"officeId é obrigatório.\");\n    if (!data.date) throw new BookingValidationError(\"date é obrigatório.\");\n    if (!data.shift) throw new BookingValidationError(\"shift é obrigatório.\");\n    if (data.offeredPrice == null || data.offeredPrice <= 0) {\n      throw new BookingValidationError(\"Informe um valor de oferta maior que zero.\");\n    }\n\n    const office = await officeRepository.findById(data.officeId);\n    if (!office) throw new BookingValidationError(\"Consultório não encontrado.\");\n    if (office.moderationStatus !== \"APROVADO\" || office.status !== \"ATIVO\") {\n      throw new BookingValidationError(\"Este consultório não está disponível para reservas no momento.\");\n    }\n\n    const dentist = await userRepository.findById(dentistId);\n    if (!dentist) throw new BookingValidationError(\"Usuário não encontrado.\");\n\n    if (office.ownerId === dentistId) {\n      throw new BookingValidationError(\"Você não pode enviar uma proposta para o seu próprio consultório.\");\n    }\n\n    // Regra: dia da semana precisa estar entre os disponibilizados pelo proprietário.\n    const parsedDate = parseDateOrThrow(data.date);\n    const weekday = JS_WEEKDAY_TO_WEEKDAY[parsedDate.getDay()];\n    if (office.availableWeekdays.length > 0 && !office.availableWeekdays.includes(weekday)) {\n      throw new BookingValidationError(\n        `Este consultório não está disponível em ${weekday}. Dias disponíveis: ${office.availableWeekdays.join(\", \")}.`\n      );\n    }\n\n    // Regra de conflito: o MESMO dentista não pode ter duas propostas\n    // pendentes/aceitas na mesma data+turno, mesmo em clínicas diferentes.\n    const conflict = await bookingRepository.findActiveConflict(dentistId, data.date, data.shift);\n    if (conflict) {\n      throw new BookingValidationError(\n        `Você já tem uma proposta ${conflict.status === \"ACEITO\" ? \"aceita\" : \"pendente\"} para ${data.date} no turno da ${data.shift.toLowerCase()} (consultório \"${conflict.officeTitle}\"). Não é possível ter dois compromissos no mesmo turno.`\n      );\n    }\n\n    // Determina o serviço/preço tabelado.\n    let serviceName = \"Turno padrão\";\n    let listedPrice = office.shiftPrices.find((sp) => sp.shift === data.shift)?.price ?? 0;\n    let serviceId: string | undefined;\n\n    if (data.serviceId) {\n      const service = office.services.find((s) => s.id === data.serviceId);\n      if (!service) throw new BookingValidationError(\"Procedimento não encontrado neste consultório.\");\n      serviceId = service.id;\n      serviceName = service.name;\n      listedPrice = service.price;\n    }\n\n    const now = new Date().toISOString();\n    const booking: BookingProposal = {\n      id: randomUUID(),\n      officeId: office.id,\n      officeTitle: office.title,\n      officeImageUrl: office.imageUrl,\n      ownerId: office.ownerId,\n      dentistId: dentist.id,\n      dentistName: dentist.name,\n      dentistAvatarUrl: dentist.avatarUrl,\n      date: data.date,\n      weekday,\n      shift: data.shift,\n      serviceId,\n      serviceName,\n      listedPrice,\n      offeredPrice: data.offeredPrice,\n      status: \"PENDENTE_APROVACAO\",\n      messages: [],\n      createdAt: now,\n      updatedAt: now,\n    };\n\n    booking.messages.push(buildAutoMessage(booking));\n\n    return bookingRepository.create(booking);\n  },\n\n  async getById(id: string): Promise<BookingProposal> {\n    const booking = await bookingRepository.findById(id);\n    if (!booking) throw new BookingValidationError(\"Proposta não encontrada.\");\n    return booking;\n  },\n\n  async listReceived(ownerId: string, status?: string): Promise<BookingProposal[]> {\n    return bookingRepository.findByOwner(ownerId, status);\n  },\n\n  async listSent(dentistId: string, status?: string): Promise<BookingProposal[]> {\n    return bookingRepository.findByDentist(dentistId, status);\n  },\n\n  async accept(id: string, actingOwnerId: string): Promise<BookingProposal> {\n    const booking = await this.getById(id);\n    if (booking.ownerId !== actingOwnerId) {\n      throw new BookingValidationError(\"Apenas o proprietário do consultório pode aceitar esta proposta.\");\n    }\n    if (booking.status === \"ACEITO\") return booking;\n\n    const updated = await bookingRepository.update(id, { status: \"ACEITO\" });\n    return updated as BookingProposal;\n  },\n\n  async reject(id: string, actingOwnerId: string): Promise<BookingProposal> {\n    const booking = await this.getById(id);\n    if (booking.ownerId !== actingOwnerId) {\n      throw new BookingValidationError(\"Apenas o proprietário do consultório pode recusar esta proposta.\");\n    }\n\n    const updated = await bookingRepository.update(id, { status: \"RECUSADO\" });\n    return updated as BookingProposal;\n  },\n\n  async addMessage(id: string, senderId: string, text: string): Promise<BookingProposal> {\n    const booking = await this.getById(id);\n    if (senderId !== booking.ownerId && senderId !== booking.dentistId) {\n      throw new BookingValidationError(\"Você não participa desta negociação.\");\n    }\n    if (!text?.trim()) throw new BookingValidationError(\"Mensagem vazia.\");\n\n    const sender = await userRepository.findById(senderId);\n    const message: ChatMessage = {\n      id: randomUUID(),\n      senderId,\n      senderName: sender?.name ?? \"Usuário\",\n      text: text.trim(),\n      createdAt: new Date().toISOString(),\n    };\n\n    const messages = [...booking.messages, message];\n    // Uma mensagem manual durante a análise inicia formalmente a negociação.\n    const nextStatus = booking.status === \"PENDENTE_APROVACAO\" ? \"NEGOCIACAO\" : booking.status;\n\n    const updated = await bookingRepository.update(id, { messages, status: nextStatus });\n    return updated as BookingProposal;\n  },\n};\n";
files["backend/src/modules/offices/office.controller.ts"] = "import { Request, Response } from \"express\";\nimport { officeService, OfficeValidationError } from \"./office.service\";\n\n// Camada de Controller: só entende HTTP (req/res).\n// Toda regra de negócio fica na Service; toda persistência, no Repository.\n\nfunction handleError(res: Response, error: unknown) {\n  if (error instanceof OfficeValidationError) {\n    return res.status(400).json({ message: error.message });\n  }\n  console.error(error);\n  return res.status(500).json({ message: \"Erro interno no servidor.\" });\n}\n\n// Garante que só o dono do consultório (ou um admin) possa alterá-lo.\nasync function assertOwnership(req: Request, res: Response, officeId: string): Promise<boolean> {\n  const office = await officeService.getById(officeId);\n  const authUser = req.authUser!;\n  if (office.ownerId !== authUser.id && authUser.role !== \"admin\") {\n    res.status(403).json({ message: \"Você não tem permissão para alterar este consultório.\" });\n    return false;\n  }\n  return true;\n}\n\nexport const officeController = {\n  async create(req: Request, res: Response) {\n    try {\n      // ownerId nunca vem do corpo da requisição — sempre do usuário autenticado.\n      const office = await officeService.create({ ...req.body, ownerId: req.authUser!.id });\n      return res.status(201).json(office);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async list(req: Request, res: Response) {\n    try {\n      const { ownerId, status, moderationStatus } = req.query;\n      const offices = await officeService.list({\n        ownerId: ownerId as string | undefined,\n        status: status as string | undefined,\n        moderationStatus: moderationStatus as string | undefined,\n      });\n      return res.status(200).json(offices);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async getById(req: Request, res: Response) {\n    try {\n      const office = await officeService.getById(req.params.id);\n      return res.status(200).json(office);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async update(req: Request, res: Response) {\n    try {\n      if (!(await assertOwnership(req, res, req.params.id))) return;\n      const office = await officeService.update(req.params.id, req.body);\n      return res.status(200).json(office);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async toggleStatus(req: Request, res: Response) {\n    try {\n      if (!(await assertOwnership(req, res, req.params.id))) return;\n      const office = await officeService.toggleStatus(req.params.id);\n      return res.status(200).json(office);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async remove(req: Request, res: Response) {\n    try {\n      if (!(await assertOwnership(req, res, req.params.id))) return;\n      await officeService.remove(req.params.id);\n      return res.status(204).send();\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n};\n";
files["backend/src/modules/offices/office.model.ts"] = "// Tipos e enums do módulo de Consultórios (Offices/Rooms)\n// Mantido isolado do restante do sistema para facilitar a extração\n// futura para um pacote compartilhado (ex: monorepo com workspaces).\n\nexport type OfficeStatus = \"ATIVO\" | \"INATIVO\";\n\n// Moderação é independente do status ATIVO/INATIVO (que é controlado\n// pelo próprio proprietário). Todo consultório novo nasce PENDENTE e só\n// aparece na busca pública depois que um admin aprova em /admin.\nexport type ModerationStatus = \"PENDENTE\" | \"APROVADO\" | \"RECUSADO\";\n\nexport type Shift = \"MANHA\" | \"TARDE\" | \"NOITE\";\n\n// Dias da semana em que o proprietário disponibiliza o consultório.\nexport type Weekday = \"SEG\" | \"TER\" | \"QUA\" | \"QUI\" | \"SEX\" | \"SAB\" | \"DOM\";\n\nexport const WEEKDAY_ORDER: Weekday[] = [\"SEG\", \"TER\", \"QUA\", \"QUI\", \"SEX\", \"SAB\", \"DOM\"];\n\n// Mapeia Date.getDay() (0=domingo) para o enum Weekday usado no sistema.\nexport const JS_WEEKDAY_TO_WEEKDAY: Record<number, Weekday> = {\n  0: \"DOM\",\n  1: \"SEG\",\n  2: \"TER\",\n  3: \"QUA\",\n  4: \"QUI\",\n  5: \"SEX\",\n  6: \"SAB\",\n};\n\n// Procedimento/serviço que pode ser realizado no consultório, com preço próprio\n// (independente do preço genérico por turno em ShiftPrice).\nexport interface OfficeService {\n  id: string;\n  name: string; // ex: \"Procedimento de Canal\"\n  price: number; // ex: 200 (R$ por turno)\n}\n\nexport interface Address {\n  street: string; // Rua/Avenida\n  number: string;\n  complement?: string;\n  neighborhood: string; // Bairro\n  city: string;\n  state: string; // UF\n  zipCode: string; // CEP\n}\n\nexport interface ShiftPrice {\n  shift: Shift;\n  price: number; // valor em reais (R$)\n}\n\nexport type Equipment =\n  | \"AUTOCLAVE\"\n  | \"RAIO_X\"\n  | \"CADEIRA_ODONTOLOGICA\"\n  | \"COMPRESSOR\"\n  | \"FOTOPOLIMERIZADOR\"\n  | \"AR_CONDICIONADO\"\n  | \"WIFI\"\n  | string; // permite equipamentos customizados além dos pré-definidos\n\nexport interface Review {\n  id: string;\n  authorName: string;\n  authorAvatarUrl: string;\n  rating: number; // 0-5\n  comment: string;\n  date: string; // ISO string\n}\n\nexport interface Office {\n  id: string;\n  ownerId: string; // ID do Proprietário\n  title: string;\n  description: string;\n  croResponsible: string; // Registro CRO do responsável técnico\n  address: Address;\n  shiftPrices: ShiftPrice[]; // Preço por turno (Manhã/Tarde/Noite)\n  equipments: Equipment[];\n  availableWeekdays: Weekday[]; // Dias da semana em que o consultório aceita reservas\n  services: OfficeService[]; // Procedimentos oferecidos, cada um com preço próprio\n  status: OfficeStatus;\n  moderationStatus: ModerationStatus;\n  imageUrl?: string; // Imagem de capa (usada no card estilo Airbnb)\n  images?: string[]; // Galeria de fotos (usada na tela de detalhes)\n  reviews?: Review[]; // Avaliações do consultório\n  rating?: number; // Avaliação média (0-5). Calculável a partir de reviews.\n  createdAt: string;\n  updatedAt: string;\n}\n\n// DTO usado na criação (id/createdAt/updatedAt são gerados pelo backend)\nexport interface CreateOfficeDTO {\n  ownerId: string;\n  title: string;\n  description: string;\n  croResponsible: string;\n  address: Address;\n  shiftPrices: ShiftPrice[];\n  equipments: Equipment[];\n  availableWeekdays: Weekday[];\n  services: OfficeService[];\n  status?: OfficeStatus;\n  moderationStatus?: ModerationStatus;\n  imageUrl?: string;\n  images?: string[];\n  reviews?: Review[];\n  rating?: number;\n}\n\n// DTO usado na atualização (todos os campos opcionais - PATCH-like)\nexport type UpdateOfficeDTO = Partial<CreateOfficeDTO>;\n";
files["backend/src/modules/offices/office.repository.ts"] = "import { randomUUID } from \"crypto\";\nimport {\n  CreateOfficeDTO,\n  Office,\n  OfficeService,\n  Review,\n  UpdateOfficeDTO,\n} from \"./office.model\";\n\n// Repositório em memória (mock). Quando o banco de dados real for\n// definido (Postgres, Mongo, etc), basta criar uma nova implementação\n// desta mesma interface (ex: OfficePrismaRepository) e trocar a\n// instância usada no controller/service, sem alterar o restante do módulo.\n\nexport interface IOfficeRepository {\n  create(data: CreateOfficeDTO): Promise<Office>;\n  findAll(filters?: { ownerId?: string; status?: string; moderationStatus?: string }): Promise<Office[]>;\n  findById(id: string): Promise<Office | null>;\n  update(id: string, data: UpdateOfficeDTO): Promise<Office | null>;\n  delete(id: string): Promise<boolean>;\n}\n\nfunction makeReview(\n  authorName: string,\n  authorAvatarUrl: string,\n  rating: number,\n  comment: string,\n  date: string\n): Review {\n  return { id: randomUUID(), authorName, authorAvatarUrl, rating, comment, date };\n}\n\n\nfunction makeService(name: string, price: number): OfficeService {\n  return { id: randomUUID(), name, price };\n}\n\nclass OfficeInMemoryRepository implements IOfficeRepository {\n  private offices: Office[] = [];\n\n  constructor() {\n    this.seed();\n  }\n\n  private seed() {\n    const demo: Array<Omit<Office, \"id\" | \"createdAt\" | \"updatedAt\">> = [\n      {\n        ownerId: \"owner-demo-01\",\n        title: \"Consultório Meireles\",\n        description:\n          \"Sala climatizada, próxima à praia, ideal para atendimentos clínicos gerais. Espaço planejado para transmitir conforto e confiança aos pacientes, com acabamento moderno e fácil acesso.\",\n        croResponsible: \"CRO-CE 10234\",\n        address: { street: \"Av. Beira Mar\", number: \"1200\", neighborhood: \"Meireles\", city: \"Fortaleza\", state: \"CE\", zipCode: \"60165-121\" },\n        shiftPrices: [{ shift: \"MANHA\", price: 250 }, { shift: \"TARDE\", price: 250 }],\n        equipments: [\"RAIO_X\", \"AUTOCLAVE\", \"AR_CONDICIONADO\", \"WIFI\"],\n        availableWeekdays: [\"SEG\", \"TER\", \"QUA\", \"QUI\", \"SEX\"],\n        services: [\n          makeService(\"Avaliação Geral\", 120),\n          makeService(\"Procedimento de Canal\", 200),\n          makeService(\"Limpeza / Profilaxia\", 150),\n        ],\n        status: \"ATIVO\",\n        moderationStatus: \"APROVADO\",\n        imageUrl: \"https://images.unsplash.com/photo-1629909613654-28e377c37b09?q=80&w=800&auto=format&fit=crop\",\n        images: [\n          \"https://images.unsplash.com/photo-1629909613654-28e377c37b09?q=80&w=1200&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1588776814546-1ffcf47267a5?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1629909615184-74f495363b67?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1629909613645-a3e0e1c3d3a3?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1609840114035-3c981b782dfe?q=80&w=800&auto=format&fit=crop\",\n        ],\n        reviews: [\n          makeReview(\"Rayane\", \"https://i.pravatar.cc/100?img=47\", 5, \"Paula é uma querida — super simpática e acolhedora. Me senti realmente em casa. A localização é excelente, com tudo por perto.\", \"2026-05-02\"),\n          makeReview(\"Adilson Oliveira\", \"https://i.pravatar.cc/100?img=12\", 4, \"Ótima localização perto de tudo. Local tranquilo, me senti em casa e a Paula é super simpática. Voltarei em breve.\", \"2026-04-18\"),\n          makeReview(\"Terra\", \"https://i.pravatar.cc/100?img=32\", 4, \"A acomodação foi incrível, assim como toda a comunicação durante a estadia. Fica próximo de praticamente tudo.\", \"2026-05-10\"),\n          makeReview(\"Vitória\", \"https://i.pravatar.cc/100?img=25\", 5, \"Ótimo ambiente, cheguei em horário desconfortável mas fui prontamente recebida. Organizado e próximo de onde eu queria.\", \"2026-04-01\"),\n        ],\n        rating: 4.9,\n      },\n      {\n        ownerId: \"owner-demo-02\",\n        title: \"Studio Odonto Aldeota\",\n        description:\n          \"Consultório compacto e moderno, ótimo para ortodontia e clínica geral. Prédio com fácil acesso e estacionamento nas proximidades.\",\n        croResponsible: \"CRO-CE 88452\",\n        address: { street: \"Rua Barão de Aracati\", number: \"540\", neighborhood: \"Aldeota\", city: \"Fortaleza\", state: \"CE\", zipCode: \"60115-081\" },\n        shiftPrices: [{ shift: \"TARDE\", price: 180 }, { shift: \"NOITE\", price: 200 }],\n        equipments: [\"CADEIRA_ODONTOLOGICA\", \"AUTOCLAVE\", \"WIFI\"],\n        availableWeekdays: [\"TER\", \"QUI\"],\n        services: [\n          makeService(\"Avaliação Ortodôntica\", 100),\n          makeService(\"Manutenção de Aparelho\", 130),\n        ],\n        status: \"ATIVO\",\n        moderationStatus: \"APROVADO\",\n        imageUrl: \"https://images.unsplash.com/photo-1588776814546-1ffcf47267a5?q=80&w=800&auto=format&fit=crop\",\n        images: [\n          \"https://images.unsplash.com/photo-1588776814546-1ffcf47267a5?q=80&w=1200&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1629909613654-28e377c37b09?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1512099192594-08b6017fc78d?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1629909615184-74f495363b67?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1517502884422-41eaead166d4?q=80&w=800&auto=format&fit=crop\",\n        ],\n        reviews: [\n          makeReview(\"Bruno Costa\", \"https://i.pravatar.cc/100?img=15\", 5, \"Espaço muito bem cuidado, o Marcelo foi super atencioso e prestativo durante toda a locação.\", \"2026-03-22\"),\n          makeReview(\"Larissa Melo\", \"https://i.pravatar.cc/100?img=44\", 4, \"Consultório funcional, bem localizado. Recomendo para quem está começando a clínica.\", \"2026-02-14\"),\n        ],\n        rating: 4.7,\n      },\n      {\n        ownerId: \"owner-demo-01\",\n        title: \"Clínica Praia do Futuro I\",\n        description:\n          \"Espaço amplo com equipamentos completos para cirurgia e implantodontia. Estrutura pensada para procedimentos mais complexos, com sala de esterilização própria.\",\n        croResponsible: \"CRO-CE 55210\",\n        address: { street: \"Av. Zezé Diogo\", number: \"3400\", neighborhood: \"Praia do Futuro\", city: \"Fortaleza\", state: \"CE\", zipCode: \"60181-901\" },\n        shiftPrices: [{ shift: \"MANHA\", price: 300 }, { shift: \"TARDE\", price: 300 }, { shift: \"NOITE\", price: 260 }],\n        equipments: [\"RAIO_X\", \"AUTOCLAVE\", \"COMPRESSOR\", \"FOTOPOLIMERIZADOR\", \"AR_CONDICIONADO\"],\n        availableWeekdays: [\"SEG\", \"QUA\", \"SEX\", \"SAB\"],\n        services: [\n          makeService(\"Extração\", 250),\n          makeService(\"Implante Dentário\", 600),\n          makeService(\"Cirurgia Simples\", 350),\n        ],\n        status: \"ATIVO\",\n        moderationStatus: \"APROVADO\",\n        imageUrl: \"https://images.unsplash.com/photo-1629909615184-74f495363b67?q=80&w=800&auto=format&fit=crop\",\n        images: [\n          \"https://images.unsplash.com/photo-1629909615184-74f495363b67?q=80&w=1200&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1629909613654-28e377c37b09?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1588776814546-1ffcf47267a5?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1609840114035-3c981b782dfe?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1512099192594-08b6017fc78d?q=80&w=800&auto=format&fit=crop\",\n        ],\n        reviews: [\n          makeReview(\"Fernanda Lima\", \"https://i.pravatar.cc/100?img=5\", 5, \"Estrutura excelente para cirurgias, equipamentos completos e bem conservados. Superou expectativas.\", \"2026-05-20\"),\n          makeReview(\"Diego Farias\", \"https://i.pravatar.cc/100?img=8\", 5, \"Sala espaçosa, ótima para procedimentos mais longos. Paula sempre disponível para qualquer dúvida.\", \"2026-04-30\"),\n          makeReview(\"Isabela Prado\", \"https://i.pravatar.cc/100?img=29\", 4, \"Muito bom custo-benefício considerando os equipamentos disponíveis no local.\", \"2026-03-11\"),\n        ],\n        rating: 4.91,\n      },\n      {\n        ownerId: \"owner-demo-03\",\n        title: \"Consultório Serrinha\",\n        description:\n          \"Casa adaptada, ambiente tranquilo, ótima para atendimentos particulares. Bairro calmo e de fácil estacionamento na rua.\",\n        croResponsible: \"CRO-CE 33012\",\n        address: { street: \"Rua das Acácias\", number: \"88\", neighborhood: \"Serrinha\", city: \"Fortaleza\", state: \"CE\", zipCode: \"60741-030\" },\n        shiftPrices: [{ shift: \"MANHA\", price: 210 }, { shift: \"TARDE\", price: 210 }],\n        equipments: [\"CADEIRA_ODONTOLOGICA\", \"WIFI\"],\n        availableWeekdays: [\"SEG\", \"TER\", \"QUA\", \"QUI\", \"SEX\", \"SAB\"],\n        services: [\n          makeService(\"Avaliação Geral\", 110),\n          makeService(\"Clareamento Dental\", 280),\n        ],\n        status: \"ATIVO\",\n        moderationStatus: \"APROVADO\",\n        imageUrl: \"https://images.unsplash.com/photo-1629909613645-a3e0e1c3d3a3?q=80&w=800&auto=format&fit=crop\",\n        images: [\n          \"https://images.unsplash.com/photo-1629909613645-a3e0e1c3d3a3?q=80&w=1200&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1517502884422-41eaead166d4?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1588776814546-1ffcf47267a5?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1629909613654-28e377c37b09?q=80&w=800&auto=format&fit=crop\",\n          \"https://images.unsplash.com/photo-1609840114035-3c981b782dfe?q=80&w=800&auto=format&fit=crop\",\n        ],\n        reviews: [\n          makeReview(\"Patrícia Nunes\", \"https://i.pravatar.cc/100?img=9\", 5, \"Ambiente muito acolhedor e tranquilo, ótimo para quem busca privacidade no atendimento.\", \"2026-05-05\"),\n          makeReview(\"Renato Alves\", \"https://i.pravatar.cc/100?img=51\", 5, \"Camila é muito atenciosa, espaço limpo e organizado. Recomendo bastante.\", \"2026-04-22\"),\n        ],\n        rating: 4.96,\n      },\n    ];\n\n    demo.forEach((office) => {\n      const now = new Date().toISOString();\n      this.offices.push({ id: randomUUID(), createdAt: now, updatedAt: now, ...office });\n    });\n  }\n\n  async create(data: CreateOfficeDTO): Promise<Office> {\n    const now = new Date().toISOString();\n    const office: Office = {\n      id: randomUUID(),\n      status: data.status ?? \"ATIVO\",\n      moderationStatus: data.moderationStatus ?? \"PENDENTE\",\n      images: data.images ?? (data.imageUrl ? [data.imageUrl] : []),\n      reviews: data.reviews ?? [],\n      createdAt: now,\n      updatedAt: now,\n      ...data,\n    };\n    this.offices.push(office);\n    return office;\n  }\n\n  async findAll(filters?: { ownerId?: string; status?: string; moderationStatus?: string }): Promise<Office[]> {\n    let result = [...this.offices];\n\n    if (filters?.ownerId) {\n      result = result.filter((o) => o.ownerId === filters.ownerId);\n    }\n\n    if (filters?.status) {\n      result = result.filter((o) => o.status === filters.status);\n    }\n\n    if (filters?.moderationStatus) {\n      result = result.filter((o) => o.moderationStatus === filters.moderationStatus);\n    }\n\n    return result.sort(\n      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()\n    );\n  }\n\n  async findById(id: string): Promise<Office | null> {\n    return this.offices.find((o) => o.id === id) ?? null;\n  }\n\n  async update(id: string, data: UpdateOfficeDTO): Promise<Office | null> {\n    const index = this.offices.findIndex((o) => o.id === id);\n    if (index === -1) return null;\n\n    const updated: Office = {\n      ...this.offices[index],\n      ...data,\n      id: this.offices[index].id, // garante imutabilidade do id\n      updatedAt: new Date().toISOString(),\n    };\n\n    this.offices[index] = updated;\n    return updated;\n  }\n\n  async delete(id: string): Promise<boolean> {\n    const sizeBefore = this.offices.length;\n    this.offices = this.offices.filter((o) => o.id !== id);\n    return this.offices.length < sizeBefore;\n  }\n}\n\n// Singleton exportado: garante que os dados em memória persistam\n// entre as requisições enquanto o servidor estiver rodando.\nexport const officeRepository: IOfficeRepository = new OfficeInMemoryRepository();\n";
files["backend/src/modules/offices/office.routes.ts"] = "import { Router } from \"express\";\nimport { officeController } from \"./office.controller\";\nimport { requireAuth } from \"../../shared/middlewares/auth.middleware\";\n\n// Todas as rotas deste módulo ficam isoladas aqui.\n// Para adicionar um novo módulo (ex: chat, reviews, payments),\n// crie uma pasta irmã em src/modules e registre as rotas em src/server.ts.\n\nconst officeRoutes = Router();\n\n// Leitura é pública (qualquer visitante pode buscar consultórios).\nofficeRoutes.get(\"/offices\", officeController.list);\nofficeRoutes.get(\"/offices/:id\", officeController.getById);\n\n// Escrita exige autenticação — o ownerId é sempre derivado do usuário\n// autenticado (req.authUser.id), nunca do corpo da requisição.\nofficeRoutes.post(\"/offices\", requireAuth, officeController.create);\nofficeRoutes.put(\"/offices/:id\", requireAuth, officeController.update);\nofficeRoutes.patch(\"/offices/:id/toggle-status\", requireAuth, officeController.toggleStatus);\nofficeRoutes.delete(\"/offices/:id\", requireAuth, officeController.remove);\n\nexport { officeRoutes };\n";
files["backend/src/modules/offices/office.service.ts"] = "import { CreateOfficeDTO, Office, UpdateOfficeDTO } from \"./office.model\";\nimport { officeRepository } from \"./office.repository\";\n\n// Camada de Serviço: concentra as regras de negócio (validações,\n// autorizações, cálculos) e conversa com o repositório.\n// O controller nunca deve acessar o repositório diretamente.\n\nexport class OfficeValidationError extends Error {\n  constructor(message: string) {\n    super(message);\n    this.name = \"OfficeValidationError\";\n  }\n}\n\nfunction validateCreateDTO(data: CreateOfficeDTO) {\n  if (!data.ownerId?.trim()) throw new OfficeValidationError(\"ownerId é obrigatório.\");\n  if (!data.title?.trim()) throw new OfficeValidationError(\"title é obrigatório.\");\n  if (!data.description?.trim()) throw new OfficeValidationError(\"description é obrigatório.\");\n  if (!data.croResponsible?.trim()) throw new OfficeValidationError(\"croResponsible é obrigatório.\");\n  if (!data.address) throw new OfficeValidationError(\"address é obrigatório.\");\n  if (!data.shiftPrices || data.shiftPrices.length === 0) {\n    throw new OfficeValidationError(\"Informe ao menos um turno com preço (shiftPrices).\");\n  }\n  data.shiftPrices.forEach((sp) => {\n    if (sp.price < 0) throw new OfficeValidationError(\"O preço do turno não pode ser negativo.\");\n  });\n  if (!data.equipments) throw new OfficeValidationError(\"equipments é obrigatório (pode ser lista vazia).\");\n  if (!data.availableWeekdays || data.availableWeekdays.length === 0) {\n    throw new OfficeValidationError(\"Selecione ao menos um dia da semana disponível.\");\n  }\n  if (!data.services) throw new OfficeValidationError(\"services é obrigatório (pode ser lista vazia).\");\n  data.services.forEach((s) => {\n    if (!s.name?.trim()) throw new OfficeValidationError(\"Todo procedimento precisa de um nome.\");\n    if (s.price < 0) throw new OfficeValidationError(\"O preço do procedimento não pode ser negativo.\");\n  });\n}\n\nexport const officeService = {\n  async create(data: CreateOfficeDTO): Promise<Office> {\n    validateCreateDTO(data);\n    // Segurança: todo consultório nasce PENDENTE, independentemente do\n    // que vier no corpo da requisição — só um admin pode aprovar.\n    return officeRepository.create({ ...data, moderationStatus: \"PENDENTE\" });\n  },\n\n  async list(filters?: { ownerId?: string; status?: string; moderationStatus?: string }): Promise<Office[]> {\n    return officeRepository.findAll(filters);\n  },\n\n  async getById(id: string): Promise<Office> {\n    const office = await officeRepository.findById(id);\n    if (!office) throw new OfficeValidationError(\"Consultório não encontrado.\");\n    return office;\n  },\n\n  async update(id: string, data: UpdateOfficeDTO): Promise<Office> {\n    if (data.shiftPrices) {\n      data.shiftPrices.forEach((sp) => {\n        if (sp.price < 0) throw new OfficeValidationError(\"O preço do turno não pode ser negativo.\");\n      });\n    }\n    const updated = await officeRepository.update(id, data);\n    if (!updated) throw new OfficeValidationError(\"Consultório não encontrado.\");\n    return updated;\n  },\n\n  async toggleStatus(id: string): Promise<Office> {\n    const office = await officeRepository.findById(id);\n    if (!office) throw new OfficeValidationError(\"Consultório não encontrado.\");\n    const newStatus = office.status === \"ATIVO\" ? \"INATIVO\" : \"ATIVO\";\n    const updated = await officeRepository.update(id, { status: newStatus });\n    return updated as Office;\n  },\n\n  async remove(id: string): Promise<void> {\n    const deleted = await officeRepository.delete(id);\n    if (!deleted) throw new OfficeValidationError(\"Consultório não encontrado.\");\n  },\n\n  // ---------- Moderação (usado pelo painel /admin) ----------\n\n  async listPending(): Promise<Office[]> {\n    return officeRepository.findAll({ moderationStatus: \"PENDENTE\" });\n  },\n\n  async approve(id: string): Promise<Office> {\n    const updated = await officeRepository.update(id, { moderationStatus: \"APROVADO\" });\n    if (!updated) throw new OfficeValidationError(\"Consultório não encontrado.\");\n    return updated;\n  },\n\n  async reject(id: string): Promise<Office> {\n    const updated = await officeRepository.update(id, { moderationStatus: \"RECUSADO\" });\n    if (!updated) throw new OfficeValidationError(\"Consultório não encontrado.\");\n    return updated;\n  },\n};\n";
files["backend/src/modules/users/user.controller.ts"] = "import { Request, Response } from \"express\";\nimport { AuthError, userService } from \"./user.service\";\n\nfunction handleError(res: Response, error: unknown) {\n  if (error instanceof AuthError) {\n    return res.status(400).json({ message: error.message });\n  }\n  console.error(error);\n  return res.status(500).json({ message: \"Erro interno no servidor.\" });\n}\n\nexport const userController = {\n  async register(req: Request, res: Response) {\n    try {\n      const result = await userService.register(req.body);\n      return res.status(201).json(result);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async login(req: Request, res: Response) {\n    try {\n      const result = await userService.login(req.body);\n      return res.status(200).json(result);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n\n  async getPublicProfile(req: Request, res: Response) {\n    try {\n      const profile = await userService.getPublicProfile(req.params.id);\n      return res.status(200).json(profile);\n    } catch (error) {\n      return handleError(res, error);\n    }\n  },\n};\n";
files["backend/src/modules/users/user.model.ts"] = "// Módulo de Usuários — cadastro único.\n// Qualquer usuário autenticado pode navegar/buscar consultórios OU\n// cadastrar o seu próprio (virando \"anfitrião\"), sem precisar de um\n// tipo de conta separado. Por isso o model não tem \"role\" fixa.\n\nexport type UserRole = \"user\" | \"admin\";\nexport type UserStatus = \"ATIVO\" | \"BANIDO\";\n\nexport interface PublicHostProfile {\n  id: string;\n  name: string;\n  avatarUrl: string;\n  bio?: string;\n  isSuperhost: boolean;\n  reviewsCount: number;\n  hostRating: number; // nota do anfitrião (não confundir com nota do consultório)\n  yearsHosting: number;\n  responseRate: number; // 0-100\n  responseTime: string; // ex: \"Responde em até 1 hora\"\n  role: UserRole;\n  status: UserStatus;\n}\n\nexport interface User extends PublicHostProfile {\n  email: string;\n  // ATENÇÃO: isto é um MOCK para prototipagem. Em produção, nunca\n  // armazene senha em texto puro — use bcrypt/argon2 + hashing de verdade.\n  passwordHash: string;\n  createdAt: string;\n}\n\nexport interface RegisterUserDTO {\n  name: string;\n  email: string;\n  password: string;\n}\n\nexport interface LoginUserDTO {\n  email: string;\n  password: string;\n}\n\n// O que a API devolve ao cliente após registro/login (nunca inclui a senha)\nexport interface AuthResponse {\n  token: string;\n  user: Omit<User, \"passwordHash\">;\n}\n";
files["backend/src/modules/users/user.repository.ts"] = "import { User } from \"./user.model\";\n\nexport interface IUserRepository {\n  create(user: User): Promise<User>;\n  findAll(): Promise<User[]>;\n  findByEmail(email: string): Promise<User | null>;\n  findById(id: string): Promise<User | null>;\n  update(id: string, patch: Partial<User>): Promise<User | null>;\n}\n\nclass UserInMemoryRepository implements IUserRepository {\n  private users: User[] = [];\n\n  constructor() {\n    this.seed();\n  }\n\n  private seed() {\n    const now = new Date().toISOString();\n    // IDs fixos \"owner-demo-XX\" para casarem com o ownerId usado no\n    // seed de consultórios (office.repository.ts). O usuário \"admin-demo-01\"\n    // é o único com role \"admin\" e serve para testar o painel /admin.\n    const demoUsers: User[] = [\n      {\n        id: \"admin-demo-01\",\n        name: \"Admin DentSpot\",\n        email: \"admin@dentspot.com\",\n        passwordHash: \"admin123\", // mock — ver aviso em user.model.ts\n        avatarUrl: \"https://api.dicebear.com/7.x/initials/svg?seed=Admin\",\n        bio: \"Conta de administração da plataforma.\",\n        isSuperhost: false,\n        reviewsCount: 0,\n        hostRating: 0,\n        yearsHosting: 0,\n        responseRate: 100,\n        responseTime: \"—\",\n        role: \"admin\",\n        status: \"ATIVO\",\n        createdAt: now,\n      },\n      {\n        id: \"owner-demo-01\",\n        name: \"Paula\",\n        email: \"paula@example.com\",\n        passwordHash: \"123456\",\n        avatarUrl: \"https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=80&w=200&auto=format&fit=crop\",\n        bio: \"Sou arquiteta, adoro viajar, colecionar experiências e conhecer pessoas. Gosto de receber e conversar, mas também sei respeitar a privacidade de quem aluga meu espaço.\",\n        isSuperhost: true,\n        reviewsCount: 323,\n        hostRating: 4.87,\n        yearsHosting: 8,\n        responseRate: 100,\n        responseTime: \"Responde em até 1 hora\",\n        role: \"user\",\n        status: \"ATIVO\",\n        createdAt: now,\n      },\n      {\n        id: \"owner-demo-02\",\n        name: \"Marcelo Dentista\",\n        email: \"marcelo@example.com\",\n        passwordHash: \"123456\",\n        avatarUrl: \"https://images.unsplash.com/photo-1560250097-0b93528c311a?q=80&w=200&auto=format&fit=crop\",\n        bio: \"Cirurgião-dentista há 12 anos, hoje também administro consultórios para colegas de profissão na região da Aldeota.\",\n        isSuperhost: false,\n        reviewsCount: 58,\n        hostRating: 4.7,\n        yearsHosting: 3,\n        responseRate: 95,\n        responseTime: \"Responde em algumas horas\",\n        role: \"user\",\n        status: \"ATIVO\",\n        createdAt: now,\n      },\n      {\n        id: \"owner-demo-03\",\n        name: \"Camila Souza\",\n        email: \"camila@example.com\",\n        passwordHash: \"123456\",\n        avatarUrl: \"https://images.unsplash.com/photo-1580489944761-15a19d654956?q=80&w=200&auto=format&fit=crop\",\n        bio: \"Tenho um espaço tranquilo na Serrinha, ótimo para quem busca privacidade e atendimento particular.\",\n        isSuperhost: false,\n        reviewsCount: 21,\n        hostRating: 4.96,\n        yearsHosting: 2,\n        responseRate: 90,\n        responseTime: \"Responde em até 1 dia\",\n        role: \"user\",\n        status: \"ATIVO\",\n        createdAt: now,\n      },\n    ];\n\n    this.users.push(...demoUsers);\n  }\n\n  async create(user: User): Promise<User> {\n    this.users.push(user);\n    return user;\n  }\n\n  async findAll(): Promise<User[]> {\n    return [...this.users].sort(\n      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()\n    );\n  }\n\n  async findByEmail(email: string): Promise<User | null> {\n    return this.users.find((u) => u.email.toLowerCase() === email.toLowerCase()) ?? null;\n  }\n\n  async findById(id: string): Promise<User | null> {\n    return this.users.find((u) => u.id === id) ?? null;\n  }\n\n  async update(id: string, patch: Partial<User>): Promise<User | null> {\n    const index = this.users.findIndex((u) => u.id === id);\n    if (index === -1) return null;\n    this.users[index] = { ...this.users[index], ...patch, id: this.users[index].id };\n    return this.users[index];\n  }\n}\n\nexport const userRepository: IUserRepository = new UserInMemoryRepository();\n";
files["backend/src/modules/users/user.routes.ts"] = "import { Router } from \"express\";\nimport { userController } from \"./user.controller\";\n\nconst userRoutes = Router();\n\nuserRoutes.post(\"/auth/register\", userController.register);\nuserRoutes.post(\"/auth/login\", userController.login);\nuserRoutes.get(\"/users/:id\", userController.getPublicProfile);\n\nexport { userRoutes };\n";
files["backend/src/modules/users/user.service.ts"] = "import { randomUUID } from \"crypto\";\nimport {\n  AuthResponse,\n  LoginUserDTO,\n  PublicHostProfile,\n  RegisterUserDTO,\n  User,\n} from \"./user.model\";\nimport { userRepository } from \"./user.repository\";\n\nexport class AuthError extends Error {\n  constructor(message: string) {\n    super(message);\n    this.name = \"AuthError\";\n  }\n}\n\nfunction toPublicUser(user: User): Omit<User, \"passwordHash\"> {\n  const { passwordHash, ...publicUser } = user;\n  return publicUser;\n}\n\n// Mock de token: NÃO usar em produção. Trocar por JWT assinado.\nfunction generateMockToken(userId: string): string {\n  return Buffer.from(`${userId}:${Date.now()}`).toString(\"base64\");\n}\n\nexport const userService = {\n  async register(data: RegisterUserDTO): Promise<AuthResponse> {\n    if (!data.name?.trim()) throw new AuthError(\"Nome é obrigatório.\");\n    if (!data.email?.trim()) throw new AuthError(\"E-mail é obrigatório.\");\n    if (!data.password || data.password.length < 6) {\n      throw new AuthError(\"A senha deve ter ao menos 6 caracteres.\");\n    }\n\n    const existing = await userRepository.findByEmail(data.email);\n    if (existing) throw new AuthError(\"Já existe uma conta com este e-mail.\");\n\n    const now = new Date().toISOString();\n    const user: User = {\n      id: randomUUID(),\n      name: data.name,\n      email: data.email,\n      passwordHash: data.password, // mock — ver aviso em user.model.ts\n      avatarUrl: `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(data.name)}`,\n      bio: \"\",\n      isSuperhost: false,\n      reviewsCount: 0,\n      hostRating: 0,\n      yearsHosting: 0,\n      responseRate: 100,\n      responseTime: \"Novo por aqui\",\n      role: \"user\",\n      status: \"ATIVO\",\n      createdAt: now,\n    };\n\n    await userRepository.create(user);\n\n    return { token: generateMockToken(user.id), user: toPublicUser(user) };\n  },\n\n  async login(data: LoginUserDTO): Promise<AuthResponse> {\n    const user = await userRepository.findByEmail(data.email);\n    if (!user || user.passwordHash !== data.password) {\n      throw new AuthError(\"E-mail ou senha inválidos.\");\n    }\n    if (user.status === \"BANIDO\") {\n      throw new AuthError(\"Esta conta foi banida da plataforma.\");\n    }\n    return { token: generateMockToken(user.id), user: toPublicUser(user) };\n  },\n\n  // Decodifica o token mock (Base64 de \"userId:timestamp\") e retorna o usuário.\n  // TODO: substituir por verificação de assinatura JWT real em produção.\n  async getUserFromToken(token: string): Promise<User | null> {\n    try {\n      const decoded = Buffer.from(token, \"base64\").toString(\"utf-8\");\n      const userId = decoded.split(\":\")[0];\n      return userRepository.findById(userId);\n    } catch {\n      return null;\n    }\n  },\n\n  async getPublicProfile(id: string): Promise<PublicHostProfile> {\n    const user = await userRepository.findById(id);\n    if (!user) throw new AuthError(\"Usuário não encontrado.\");\n    const { email, passwordHash, ...publicProfile } = user;\n    return publicProfile;\n  },\n\n  // ---------- Operações administrativas ----------\n\n  async listAll(): Promise<Array<Omit<User, \"passwordHash\">>> {\n    const users = await userRepository.findAll();\n    return users.map(toPublicUser);\n  },\n\n  async toggleBan(id: string): Promise<Omit<User, \"passwordHash\">> {\n    const user = await userRepository.findById(id);\n    if (!user) throw new AuthError(\"Usuário não encontrado.\");\n    const newStatus = user.status === \"ATIVO\" ? \"BANIDO\" : \"ATIVO\";\n    const updated = await userRepository.update(id, { status: newStatus });\n    return toPublicUser(updated as User);\n  },\n\n  async togglePromote(id: string): Promise<Omit<User, \"passwordHash\">> {\n    const user = await userRepository.findById(id);\n    if (!user) throw new AuthError(\"Usuário não encontrado.\");\n    const newRole = user.role === \"admin\" ? \"user\" : \"admin\";\n    const updated = await userRepository.update(id, { role: newRole });\n    return toPublicUser(updated as User);\n  },\n};\n";
files["backend/src/server.ts"] = "import express, { NextFunction, Request, Response } from \"express\";\nimport cors from \"cors\";\nimport { officeRoutes } from \"./modules/offices/office.routes\";\nimport { userRoutes } from \"./modules/users/user.routes\";\nimport { adminRoutes } from \"./modules/admin/admin.routes\";\nimport { bookingRoutes } from \"./modules/bookings/booking.routes\";\n\nconst app = express();\nconst PORT = process.env.PORT || 3333;\n\napp.use(cors());\napp.use(express.json());\n\n// Healthcheck simples\napp.get(\"/health\", (_req, res) => {\n  res.json({ status: \"ok\", service: \"dental-marketplace-api\" });\n});\n\n// Registro dos módulos (feature-based).\n// Ex futuro: app.use(\"/api\", chatRoutes); app.use(\"/api\", reviewRoutes);\napp.use(\"/api\", officeRoutes);\napp.use(\"/api\", userRoutes);\napp.use(\"/api\", adminRoutes);\napp.use(\"/api\", bookingRoutes);\n\n// 404 padrão\napp.use((_req: Request, res: Response) => {\n  res.status(404).json({ message: \"Rota não encontrada.\" });\n});\n\n// Handler de erro global (fallback de segurança)\napp.use((err: Error, _req: Request, res: Response, _next: NextFunction) => {\n  console.error(err);\n  res.status(500).json({ message: \"Erro interno no servidor.\" });\n});\n\napp.listen(PORT, () => {\n  console.log(`🦷 API do Dental Marketplace rodando em http://localhost:${PORT}`);\n  console.log(`   Healthcheck: http://localhost:${PORT}/health`);\n  console.log(`   Consultórios: http://localhost:${PORT}/api/offices`);\n});\n";
files["backend/src/shared/middlewares/auth.middleware.ts"] = "import { NextFunction, Request, Response } from \"express\";\nimport { userService } from \"../../modules/users/user.service\";\nimport { User } from \"../../modules/users/user.model\";\n\n// Estende o tipo Request do Express para carregar o usuário autenticado.\ndeclare global {\n  // eslint-disable-next-line @typescript-eslint/no-namespace\n  namespace Express {\n    interface Request {\n      authUser?: Omit<User, \"passwordHash\">;\n    }\n  }\n}\n\n/**\n * Exige um usuário autenticado (qualquer role).\n * Lê o token mock do header \"Authorization: Bearer <token>\".\n * TODO: substituir a verificação do token mock por validação de JWT real.\n */\nexport async function requireAuth(req: Request, res: Response, next: NextFunction) {\n  const authHeader = req.headers.authorization;\n  const token = authHeader?.startsWith(\"Bearer \") ? authHeader.slice(7) : undefined;\n\n  if (!token) {\n    return res.status(401).json({ message: \"Token de autenticação ausente.\" });\n  }\n\n  const user = await userService.getUserFromToken(token);\n  if (!user) {\n    return res.status(401).json({ message: \"Token inválido ou expirado.\" });\n  }\n\n  if (user.status === \"BANIDO\") {\n    return res.status(403).json({ message: \"Esta conta foi banida da plataforma.\" });\n  }\n\n  const { passwordHash, ...safeUser } = user;\n  req.authUser = safeUser;\n  next();\n}\n\n/**\n * Exige um usuário autenticado com role === \"admin\".\n * Deve ser usado sempre em conjunto/depois de requireAuth.\n */\nexport async function requireAdmin(req: Request, res: Response, next: NextFunction) {\n  await requireAuth(req, res, () => {\n    if (req.authUser?.role !== \"admin\") {\n      return res.status(403).json({ message: \"Acesso restrito a administradores.\" });\n    }\n    next();\n  });\n}\n";
files["backend/tsconfig.json"] = "{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"module\": \"commonjs\",\n    \"lib\": [\"ES2020\"],\n    \"outDir\": \"dist\",\n    \"rootDir\": \"src\",\n    \"strict\": true,\n    \"esModuleInterop\": true,\n    \"skipLibCheck\": true,\n    \"forceConsistentCasingInFileNames\": true,\n    \"resolveJsonModule\": true,\n    \"moduleResolution\": \"node\",\n    \"declaration\": false,\n    \"sourceMap\": true\n  },\n  \"include\": [\"src/**/*.ts\"],\n  \"exclude\": [\"node_modules\", \"dist\"]\n}\n";
files["frontend/.env.example"] = "VITE_API_URL=http://localhost:3333/api\n";
files["frontend/.gitignore"] = "node_modules\ndist\n.env\n";
files["frontend/index.html"] = "<!doctype html>\n<html lang=\"pt-BR\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Dental Marketplace - Consultórios</title>\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.tsx\"></script>\n  </body>\n</html>\n";
